export function bookForVersion(version='A'){
  const v=String(version||'A').toUpperCase()==='B'?'B':'A';
  return C.map(ch=>({...ch,...(LESSON_GUIDES[ch.id]||{}),...(FINAL_ROUND[ch.id]||{}),challengeText:ch.challenge[v],challengeEdition:v}));
}

